import time
from taf.ul.mobile.ui.android.mobile import Mobile
from taf.ul.mobile.ui.android.utils import search_nodes_with_resource_id, fetch_node_bounds
from taf.ul.mobile.ui.android.exceptions import DebugLoggerOperatingFailed


class Petrus(Mobile):

    _ENTER_INTO_ATCOMMAND_EXECUTOR_CODE = "*#*#3646633#*#*"
    _CALL_BUTTON_IN_DAIL = "com.android.dialer:id/dialpad_floating_action_button"
    _INCALLL_END_BUTTON = "com.android.dialer:id/incall_end_call"
    _POWER_OFF_SIM_CARD_AT_COMMAND = "AT+ESIMPOWER=0"
    _POWER_ON_SIM_CARD_AT_COMMAND = "AT+ESIMPOWER=1"

    _RETURN_TO_HOME_PAGE_TIMES = 8
    _DEL_CHARS_NUM_IN_COMMAND_INPUT = 5

    _DEBUGLOGGER_APP_ACTIVITY = "com.debug.loggerui/com.debug.loggerui.MainActivity"

    _DEBUGLOGGER_LOG_STARTSTOP_BUTTONS = {"MobileLog": "com.debug.loggerui:id/mobileLogStartStopToggleButton",
                                          "ModemLog": "com.debug.loggerui:id/modemLogStartStopToggleButton",
                                          "NetworkLog": "com.debug.loggerui:id/networkLogStartStopToggleButton",
                                          "ConnsysLog": "com.debug.loggerui:id/connsysLogStartStopToggleButton",
                                          "All": "com.debug.loggerui:id/startStopToggleButton"}

    def set_sim_power_off(self, sim_card_name):
        self._open_sim_card_at_command_input_window(sim_card_name)
        self._execute_at_command(self._POWER_OFF_SIM_CARD_AT_COMMAND)
        self.return_to_parentlevel_with_times(self._RETURN_TO_HOME_PAGE_TIMES)

    def set_sim_power_on(self, sim_card_name):
        self._open_sim_card_at_command_input_window(sim_card_name)
        self._execute_at_command(self._POWER_ON_SIM_CARD_AT_COMMAND)
        self.return_to_parentlevel_with_times(self._RETURN_TO_HOME_PAGE_TIMES)

    def _open_sim_card_at_command_input_window(self, sim_card_name):
        self._open_engineer_mode_window()
        self._switch_to_connectivity()
        self._open_cds_information()
        self._open_radio_information()
        self._select_sim_card(sim_card_name)

    def _open_engineer_mode_window(self):
        self._adb_proxy.force_stop_dail()
        self._adb_proxy.start_dail()
        self._adb_proxy.input_text(self._ENTER_INTO_ATCOMMAND_EXECUTOR_CODE)

    def _switch_to_connectivity(self):
        from_pos = (int(self._window_x * 0.8), int(self._window_y / 2))
        to_pos = (int(self._window_x * 0.2), int(self._window_y / 2))
        self._adb_proxy.wipe_screen(from_position=from_pos, to_position=to_pos)

    def _open_cds_information(self):
        self._click_menu("CDS Information")

    def _open_radio_information(self):
        self._click_menu("Radio Information")

    def _select_sim_card(self, name):
        self._click_menu(name)

    def _execute_at_command(self, command):
        self._clear_command_input()
        self._adb_proxy.input_text(command)
        self._click_menu("SEND AT COMMAND")
        time.sleep(1)

    def _clear_command_input(self):
        chars_for_locating_input = "0"
        self._adb_proxy.input_text(chars_for_locating_input)

        for _ in range(self._DEL_CHARS_NUM_IN_COMMAND_INPUT):
            self._adb_proxy.input_forward_delete_key()

        for _ in range(len(chars_for_locating_input)):
            self._adb_proxy.input_delete_key()

    def start_emergency_call(self, number):
        self._adb_proxy.force_stop_dail()
        self._adb_proxy.start_dial_with_number(number)
        self.click_menu_by_resource_id(self._CALL_BUTTON_IN_DAIL)

    def stop_emergency_call(self):
        self.click_menu_by_resource_id(self._INCALLL_END_BUTTON)
        self._adb_proxy.force_stop_dail()

    def start_debuglogger(self, waiting_time):
        if self._is_debuglogger_started():
            return

        self._tap_debuglogger_startstop_button()

        time.sleep(waiting_time)
        if not self._is_debuglogger_started():
            raise DebugLoggerOperatingFailed("start debuglogger failed")

    def stop_debuglogger(self, waiting_time):
        if not self._is_debuglogger_started():
            return

        self._tap_debuglogger_startstop_button()

        time.sleep(waiting_time)
        if self._is_debuglogger_started():
            raise DebugLoggerOperatingFailed("stop debuglogger failed")

    def start_modemlog(self, waiting_time):
        if self._is_log_recording("ModemLog"):
            return

        self._tap_log_startstop_button("ModemLog")

        time.sleep(waiting_time)
        if not self._is_log_recording("ModemLog"):
            raise DebugLoggerOperatingFailed("start modem log failed")

    def stop_modemlog(self, waiting_time):
        if not self._is_log_recording("ModemLog"):
            return

        self._tap_log_startstop_button("ModemLog")

        time.sleep(waiting_time)
        if self._is_log_recording("ModemLog"):
            raise DebugLoggerOperatingFailed("stop modem log failed")

    def _is_debuglogger_started(self):
        return self._is_log_recording("All")

    def _tap_debuglogger_startstop_button(self):
        self._tap_log_startstop_button("All")

    def _is_log_recording(self, logtype):
        output = self._adb_proxy.start_app_activity(self._DEBUGLOGGER_APP_ACTIVITY)
        if output and "Error" in output:
            raise DebugLoggerOperatingFailed("start app failed {}".format(output))
        ui_xml_content = self._adb_proxy.get_ui_xml_content()
        resource_id = self._get_log_button_resource_id(logtype)
        node = search_nodes_with_resource_id(ui_xml_content, resource_id)[0]
        if node.get("checked") == "false":
            return False
        return True

    def _tap_log_startstop_button(self, logtype):
        output = self._adb_proxy.start_app_activity(self._DEBUGLOGGER_APP_ACTIVITY)
        if output and "Error" in output:
            raise DebugLoggerOperatingFailed("start app failed {}".format(output))
        ui_xml_content = self._adb_proxy.get_ui_xml_content()
        resource_id = self._get_log_button_resource_id(logtype)
        node = search_nodes_with_resource_id(ui_xml_content, resource_id)[0]
        node_bounds = fetch_node_bounds(node)
        self._tap_menu_by_bounds(node_bounds)

    def _get_log_button_resource_id(self, logtype):
        for name, resource_id in self._DEBUGLOGGER_LOG_STARTSTOP_BUTTONS.items():
            if name.lower() == logtype.lower():
                return resource_id
        raise DebugLoggerOperatingFailed("specified log {} not supported".format(logtype))
